16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "registration_date")
65	    private LocalDate registrationDate;
66	
67	    @Column(name = "birth_date")
68	    private LocalDate birthDate;
69	
70	    @Column(name = "customer_code")
71	    private String customerCode;
72	
73	    @Column(name = "household_id")
74	    private String householdId;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "membership_number")
80	    private String membershipNumber;
81	
82	    @Column(name = "bulk_signup_warning")
83	    private Boolean bulkSignupWarning;
84	
85	    @Column(name = "household_size")
86	    private Integer householdSize;
87	
88	    @Column(name = "postcode")
89	    private String postcode;
90	
91	    @Column(name = "possible_duplicate_of")
92	    private Integer possibleDuplicateOf;
93	
94	    @Column(name = "membership_level_cap")
95	    private Integer membershipLevelCap;
96	
97	    @Column(name = "deleted", nullable = false)
98	    private boolean deleted;
99	
100	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
101	    private Set<Pet> pets;
102	
103	    public String getTitle() {
104	        return this.title;
105	    }
106	
107	    public void setTitle(String title) {
108	        this.title = title;
109	    }
110	
111	    public String getAddress() {
112	        return this.address;
113	    }
114	
115	    public void setAddress(String address) {
116	        this.address = address;
117	    }
118	
119	    /**
120	     * The first line of this owner's structured postal address, or {@code null} when the owner was
121	     * created with only the flat {@link #getAddress() address}. Preferred over the flat address when
122	     * present; see {@link #getAddress()} for the composed form.
123	     */
124	    public String getAddressLine1() {
125	        return this.addressLine1;
126	    }
127	
128	    public void setAddressLine1(String addressLine1) {
129	        this.addressLine1 = addressLine1;
130	    }
131	
132	    /**
133	     * The optional second line of this owner's structured postal address, or {@code null} when none
134	     * was supplied. When present it is appended to {@link #getAddressLine1() addressLine1} in the
135	     * composed {@link #getAddress() address}.
136	     */
137	    public String getAddressLine2() {
138	        return this.addressLine2;
139	    }
140	
141	    public void setAddressLine2(String addressLine2) {
142	        this.addressLine2 = addressLine2;
143	    }
144	
145	    public String getCity() {
146	        return this.city;
147	    }
148	
149	    public void setCity(String city) {
150	        this.city = city;
151	    }
152	
153	    public String getTelephone() {
154	        return this.telephone;
155	    }
156	
157	    public void setTelephone(String telephone) {
158	        this.telephone = telephone;
159	    }
160	
161	    /**
162	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
163	     * as the calling code, a space, then the national digits grouped in threes, e.g.
164	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
165	     */
166	    @Transient
167	    public String getTelephoneDisplay() {
168	        return TelephoneFormatter.toDisplay(this.telephone);
169	    }
170	
171	    public String getEmail() {
172	        return this.email;
173	    }
174	
175	    public void setEmail(String email) {
176	        this.email = email;
177	    }
178	
179	    public LocalDate getRegistrationDate() {
180	        return this.registrationDate;
181	    }
182	
183	    public void setRegistrationDate(LocalDate registrationDate) {
184	        this.registrationDate = registrationDate;
185	    }
186	
187	    /**
188	     * Return this owner's fiscal year, formatted {@code FY<YY>}, derived from the (business-day
189	     * adjusted) {@code registrationDate}. The fiscal year starts on 1 July and is named by the
190	     * calendar year in which it ends. {@code null} when no registration date is known.
191	     */
192	    @Transient
193	    public String getFiscalYear() {
194	        return this.registrationDate == null ? null : FiscalYear.of(this.registrationDate).getLabel();
195	    }
196	
197	    public LocalDate getBirthDate() {
198	        return this.birthDate;
199	    }
200	
201	    public void setBirthDate(LocalDate birthDate) {
202	        this.birthDate = birthDate;
203	    }
204	
205	    public String getCustomerCode() {
206	        return this.customerCode;
207	    }
208	
209	    public void setCustomerCode(String customerCode) {
210	        this.customerCode = customerCode;
211	    }
212	
213	    public String getHouseholdId() {
214	        return this.householdId;
215	    }
216	
217	    public void setHouseholdId(String householdId) {
218	        this.householdId = householdId;
219	    }
220	
221	    public Integer getNamesakeCount() {
222	        return this.namesakeCount;
223	    }
224	
225	    public void setNamesakeCount(Integer namesakeCount) {
226	        this.namesakeCount = namesakeCount;
227	    }
228	
229	    public String getMembershipNumber() {
230	        return this.membershipNumber;
231	    }
232	
233	    public void setMembershipNumber(String membershipNumber) {
234	        this.membershipNumber = membershipNumber;
235	    }
236	
237	    /**
238	     * Whether this owner was created after more than 80 owners had already been registered on the
239	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
240	     */
241	    public Boolean getBulkSignupWarning() {
242	        return this.bulkSignupWarning;
243	    }
244	
245	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
246	        this.bulkSignupWarning = bulkSignupWarning;
247	    }
248	
249	    /**
250	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
251	     * counting this owner) captured once at creation.
252	     */
253	    public Integer getHouseholdSize() {
254	        return this.householdSize;
255	    }
256	
257	    public void setHouseholdSize(Integer householdSize) {
258	        this.householdSize = householdSize;
259	    }
260	
261	    /**
262	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
263	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
264	     */
265	    public String getPostcode() {
266	        return this.postcode;
267	    }
268	
269	    public void setPostcode(String postcode) {
270	        this.postcode = postcode;
271	    }
272	
273	    /**
274	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
275	     * creation, or {@code null} when none. Set at creation when an existing owner shares this
276	     * owner's {@code soundex(lastName)} and postcode but has a different {@link #getIdentityKey()
277	     * identity key} (e.g. a different telephone), so the two are not a hard duplicate. Captured
278	     * once at creation.
279	     */
280	    public Integer getPossibleDuplicateOf() {
281	        return this.possibleDuplicateOf;
282	    }
283	
284	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
285	        this.possibleDuplicateOf = possibleDuplicateOf;
286	    }
287	
288	    /**
289	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
290	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
291	     */
292	    @Transient
293	    public Boolean getPossibleDuplicate() {
294	        return this.possibleDuplicateOf != null;
295	    }
296	
297	    /**
298	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: one above
299	     * the highest membership level among the household members that already existed when this owner
300	     * was created, or {@code null} when the owner joined no existing household and is therefore
301	     * uncapped. Captured once at creation.
302	     */
303	    public Integer getMembershipLevelCap() {
304	        return this.membershipLevelCap;
305	    }
306	
307	    public void setMembershipLevelCap(Integer membershipLevelCap) {
308	        this.membershipLevelCap = membershipLevelCap;
309	    }
310	
311	    /**
312	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; deleting an owner
313	     * flags it {@code true} and retains the record rather than removing it. Duplicate and identity
314	     * checks at creation ignore owners flagged deleted.
315	     */
316	    public boolean isDeleted() {
317	        return this.deleted;
318	    }
319	
320	    public void setDeleted(boolean deleted) {
321	        this.deleted = deleted;
322	    }
323	
324	    /**
325	     * Return this owner's canonical API path, being {@code "/api/owners/"} followed by this owner's
326	     * {@link #getId() id}.
327	     */
328	    @Transient
329	    public String getSelfLink() {
330	        return "/api/owners/" + this.getId();
331	    }
332	
333	    /**
334	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
335	     */
336	    @Transient
337	    public String getDisplayName() {
338	        return this.getLastName() + ", " + this.getFirstName();
339	    }
340	
341	    /**
342	     * Return this owner's salutation as the {@link #getTitle() title} and last name separated by a
343	     * space (e.g. {@code "DR Who"}), or just the last name when no title was supplied.
344	     */
345	    @Transient
346	    public String getSalutation() {
347	        return (this.title == null || this.title.isBlank())
348	            ? this.getLastName()
349	            : this.title + " " + this.getLastName();
350	    }
351	
352	    /**
353	     * Return this owner's initials as the upper-cased first letters of the first and last
354	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
355	     */
356	    @Transient
357	    public String getInitials() {
358	        return initial(this.getFirstName()) + initial(this.getLastName());
359	    }
360	
361	    private static String initial(String name) {
362	        return Character.toUpperCase(name.charAt(0)) + ".";
363	    }
364	
365	    /** Points awarded when an email address is present. */
366	    private static final int EMAIL_POINTS = 2;
367	
368	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
369	    private static final int NO_NAMESAKE_POINTS = 1;
370	
371	    /** Points awarded for belonging to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more. */
372	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
373	
374	    /** The household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} are awarded. */
375	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
376	
377	    /** Points awarded for qualifying tenure. */
378	    private static final int TENURE_POINTS = 3;
379	
380	    /** The tenure, in elapsed fiscal years, that must be exceeded to earn {@link #TENURE_POINTS}. */
381	    private static final long MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS = 1;
382	
383	    /**
384	     * Return this owner's membership points, starting at 0: add {@value #EMAIL_POINTS} when an email
385	     * address is present; add {@value #NO_NAMESAKE_POINTS} when the owner has no namesakes
386	     * ({@code namesakeCount} is 0); add {@value #LARGE_HOUSEHOLD_POINTS} for a household of
387	     * {@value #LARGE_HOUSEHOLD_SIZE} or more; add {@value #TENURE_POINTS} for qualifying tenure
388	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed fiscal year since registration).
389	     */
390	    @Transient
391	    public Integer getMembershipPoints() {
392	        int points = 0;
393	        if (hasEmail()) {
394	            points += EMAIL_POINTS;
395	        }
396	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
397	            points += NO_NAMESAKE_POINTS;
398	        }
399	        if (hasLargeHousehold()) {
400	            points += LARGE_HOUSEHOLD_POINTS;
401	        }
402	        if (hasQualifyingTenure()) {
403	            points += TENURE_POINTS;
404	        }
405	        return points;
406	    }
407	
408	    /**
409	     * Return this owner's membership level, derived from {@link #getMembershipPoints() membership
410	     * points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more; then limited to the
411	     * owner's {@link #getMembershipLevelCap() membership-level ceiling} when one applies.
412	     */
413	    @Transient
414	    public Integer getMembershipLevel() {
415	        int level = membershipLevelFromPoints();
416	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
417	            return this.membershipLevelCap;
418	        }
419	        return level;
420	    }
421	
422	    /** Map this owner's {@link #getMembershipPoints() membership points} to the uncapped level. */
423	    private int membershipLevelFromPoints() {
424	        int points = getMembershipPoints();
425	        if (points <= 1) {
426	            return 1;
427	        }
428	        if (points <= 3) {
429	            return 2;
430	        }
431	        if (points <= 5) {
432	            return 3;
433	        }
434	        return 4;
435	    }
436	
437	    /**
438	     * Whether this owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more, per the
439	     * {@code householdSize} captured at creation. Owners without a recorded household size do not
440	     * qualify.
441	     */
442	    private boolean hasLargeHousehold() {
443	        return this.householdSize != null && this.householdSize >= LARGE_HOUSEHOLD_SIZE;
444	    }
445	
446	    /**
447	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed
448	     * fiscal year, i.e. more than that many fiscal years have elapsed between the fiscal year of the
449	     * {@code registrationDate} and the fiscal year of today. Owners without a registration date have
450	     * no measurable tenure and do not qualify.
451	     */
452	    private boolean hasQualifyingTenure() {
453	        if (this.registrationDate == null) {
454	            return false;
455	        }
456	        long elapsedFiscalYears = FiscalYear.of(this.registrationDate).yearsUntil(FiscalYear.of(LocalDate.now()));
457	        return elapsedFiscalYears > MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS;
458	    }
459	
460	    /** Whether this owner has a usable email address (present and not blank). */
461	    private boolean hasEmail() {
462	        return this.email != null && !this.email.isBlank();
463	    }
464	
465	    /**
466	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
467	     * present, otherwise {@code "PHONE"}.
468	     */
469	    @Transient
470	    public String getContactPreference() {
471	        return hasEmail() ? "EMAIL" : "PHONE";
472	    }
473	
474	    /**
475	     * Return this owner's age band derived from the {@code birthDate} as of the
476	     * {@code registrationDate}, or {@code null} when no birth date is known.
477	     */
478	    @Transient
479	    public AgeBand getAgeBand() {
480	        if (this.birthDate == null || this.registrationDate == null) {
481	            return null;
482	        }
483	        return AgeBand.asOf(this.birthDate, this.registrationDate);
484	    }
485	
486	    /**
487	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
488	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
489	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
490	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
491	     * region is resolved directly from the postcode and city.
492	     */
493	    @Transient
494	    public String getLocality() {
495	        if (this.customerCode == null) {
496	            return LocalityResolver.regionFor(this.postcode, this.city);
497	        }
498	        int separator = this.customerCode.indexOf('-');
499	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
500	    }
501	
502	    /**
503	     * Return this owner's timezone: the IANA timezone name for the owner's {@link #getLocality()
504	     * locality} via the fixed region-to-timezone table, or {@code null} when the locality has no
505	     * known timezone.
506	     */
507	    @Transient
508	    public String getTimezone() {
509	        return LocalityResolver.timezoneFor(getLocality());
510	    }
511	
512	    /**
513	     * Return this owner's check digit: the single Luhn check digit computed over the digits of the
514	     * {@code customerCode}.
515	     */
516	    @Transient
517	    public Integer getCheckDigit() {
518	        return this.customerCode == null ? null : LuhnCheckDigit.of(this.customerCode);
519	    }
520	
521	    /**
522	     * Return this owner's identity key, the single derived value all duplicate detection is based
523	     * on: the lower-case SHA-256 hex digest over {@code normalizedTelephone + "|" + lowerEmail +
524	     * "|" + soundex(lastName)}, with an absent email rendered as the empty string. Two owners are
525	     * duplicates only when their whole identity keys are equal; because the telephone is part of
526	     * the key, two owners with the same last name and postcode but different telephones have
527	     * distinct keys and are not duplicates (they are instead flagged as a soft match).
528	     */
529	    @Transient
530	    public String getIdentityKey() {
531	        String core = keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + Soundex.encode(this.getLastName());
532	        return Sha256Hex.lowerHex(core);
533	    }
534	
535	    private static String keyPart(String value) {
536	        return value == null ? "" : value;
537	    }
538	
539	    protected Set<Pet> getPetsInternal() {
540	        if (this.pets == null) {
541	            this.pets = new HashSet<>();
542	        }
543	        return this.pets;
544	    }
545	
546	    protected void setPetsInternal(Set<Pet> pets) {
547	        this.pets = pets;
548	    }
549	
550	    public List<Pet> getPets() {
551	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
552	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
553	        return Collections.unmodifiableList(sortedPets);
554	    }
555	
556	    public void setPets(List<Pet> pets) {
557	        this.pets = new HashSet<>(pets);
558	    }
559	
560	    public void addPet(Pet pet) {
561	        getPetsInternal().add(pet);
562	        pet.setOwner(this);
563	    }
564	
565	    /**
566	     * Return the Pet with the given name, or null if none found for this Owner.
567	     *
568	     * @param name to test
569	     * @return true if pet name is already in use
570	     */
571	    public Pet getPet(String name) {
572	        return getPet(name, false);
573	    }
574	
575	    /**
576	     * Return the Pet with the given name, or null if none found for this Owner.
577	     *
578	     * @param name to test
579	     * @return true if pet name is already in use
580	     */
581	    public Pet getPet(String name, boolean ignoreNew) {
582	        name = name.toLowerCase();
583	        for (Pet pet : getPetsInternal()) {
584	            if (!ignoreNew || !pet.isNew()) {
585	                String compName = pet.getName();
586	                compName = compName.toLowerCase();
587	                if (compName.equals(name)) {
588	                    return pet;
589	                }
590	            }
591	        }
592	        return null;
593	    }
594	
595	    public Pet getPet(Integer petId) {
596	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
597	    }
598	
599	    @Override
600	    public String toString() {
601	        return new ToStringCreator(this)
602	
603	            .append("id", this.getId())
604	            .append("new", this.isNew())
605	            .append("lastName", this.getLastName())
606	            .append("firstName", this.getFirstName())
607	            .append("address", this.address)
608	            .append("city", this.city)
609	            .append("telephone", this.telephone)
610	            .append("email", this.email)
611	            .append("registrationDate", this.registrationDate)
612	            .toString();
613	    }
614	}
