208	    /**
209	     * Canonicalize the request's address fields in place, preferring the structured form. When a
210	     * non-blank {@code addressLine1} is supplied it and the optional {@code addressLine2} are
211	     * normalized and the composed value stored on {@code address}; otherwise only the flat
212	     * {@code address} is normalized. This keeps the stored {@code address} the single canonical
213	     * value everything downstream reads.
214	     */
215	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
216	        if (ownerFieldsDto.getAddressLine1() != null && !ownerFieldsDto.getAddressLine1().isBlank()) {
217	            ownerFieldsDto.setAddressLine1(this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine1()));
218	            String line2 = this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
219	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
220	            ownerFieldsDto.setAddress(
221	                this.addressNormalizer.compose(ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2()));
222	        }
223	        else {
224	            ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
225	        }
226	    }
