242	    @Override
243	    @Transactional
244	    public void saveOwner(Owner owner) throws DataAccessException {
245	        if (owner.isNew() && owner.getCustomerCode() == null) {
246	            String region = LocalityResolver.regionFor(owner.getPostcode(), owner.getCity());
247	            String customerCode =
248	                customerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName());
249	            owner.setCustomerCode(deduplicateCustomerCode(customerCode));
250	        }
251	        if (owner.isNew() && owner.getNamesakeCount() == null) {
252	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
253	        }
254	        if (owner.isNew() && owner.getMembershipNumber() == null) {
255	            owner.setMembershipNumber(
256	                membershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
257	        }
258	        if (owner.isNew() && owner.getHouseholdSize() == null) {
259	            owner.setHouseholdSize(countHouseholdMembers(owner));
260	        }
261	        if (owner.isNew() && owner.getMembershipLevelCap() == null) {
262	            owner.setMembershipLevelCap(computeMembershipLevelCap(owner));
263	        }
264	        ownerRepository.save(owner);
265	    }
