267	    /**
268	     * Count the members of the given (not yet persisted) owner's household: the already stored
269	     * owners sharing its {@code householdId} plus the owner itself. An owner with no household
270	     * ({@code householdId} is null) is a household of one. Used to capture an owner's household
271	     * size at creation time.
272	     */
273	    private int countHouseholdMembers(Owner owner) {
274	        String householdId = owner.getHouseholdId();
275	        if (householdId == null) {
276	            return 1;
277	        }
278	        long existing = ownerRepository.findAll().stream()
279	            .filter(existingOwner -> householdId.equals(existingOwner.getHouseholdId()))
280	            .count();
281	        return (int) (existing + 1);
282	    }
283	
284	    /**
285	     * Determine the membership-level ceiling for the given (not yet persisted) owner: one above the
286	     * highest {@link Owner#getMembershipLevel() membership level} among the already stored,
287	     * non-deleted members of its household (owners sharing its {@code householdId}). Returns
288	     * {@code null} when the owner has no household ({@code householdId} is null) or no existing
289	     * household member, in which case no ceiling applies. Used to cap an owner's membership level
290	     * at creation time.
291	     */
292	    private Integer computeMembershipLevelCap(Owner owner) {
293	        String householdId = owner.getHouseholdId();
294	        if (householdId == null) {
295	            return null;
296	        }
297	        OptionalInt maxLevel = ownerRepository.findAll().stream()
298	            .filter(existing -> !existing.isDeleted())
299	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
300	            .mapToInt(Owner::getMembershipLevel)
301	            .max();
302	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
303	    }
